TLM.f("Tempora/Pasc5-1r",{"officium":"Feria Secunda in Rogationibus","rule":["Gloria","no Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"fallback":"Tempora/Pasc5-0","from":{"Introitus":"Tempora/Pasc5-0","Oratio":"Tempora/Pasc5-0","Lectio":"Tempora/Pasc5-0","Graduale":"Tempora/Pasc5-0","Evangelium":"Tempora/Pasc5-0","Offertorium":"Tempora/Pasc5-0","Secreta":"Tempora/Pasc5-0","Communio":"Tempora/Pasc5-0","Postcommunio":"Tempora/Pasc5-0"},"sections":{"Introitus":[{"k":"ref","la":"Isa 48:20"},{"k":"text","la":"Vocem jucunditátis annuntiáte, et audiátur, allelúja: annuntiáte usque ad extrémum terræ: liberávit Dóminus pópulum suum, allelúja, allelúja."},{"k":"ref","la":"Ps 65:1-2"},{"k":"text","la":"Jubiláte Deo, omnis terra, psalmum dícite nómini ejus: date glóriam laudi ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Vocem jucunditátis annuntiáte, et audiátur, allelúja: annuntiáte usque ad extrémum terræ: liberávit Dóminus pópulum suum, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, a quo bona cuncta procédunt, largíre supplícibus tuis: ut cogitémus, te inspiránte, quæ recta sunt; et, te gubernánte, éadem faciámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Jacóbi Apóstoli"},{"k":"ref","la":"Jas 1:22-27"},{"k":"text","la":"Caríssimi: Estóte factóres verbi, et non auditóres tantum: falléntes vosmetípsos. Quia si quis audítor est verbi et non factor: hic comparábitur viro consideránti vultum nativitátis suæ in spéculo: considerávit enim se et ábiit, et statim oblítus est, qualis fúerit. Qui autem perspéxerit in legem perfectam libertátis et permánserit in ea, non audítor obliviósus factus, sed factor óperis: hic beátus in facto suo erit. Si quis autem putat se religiósum esse, non refrénans linguam suam, sed sedúcens cor suum, hujus vana est relígio. Relígio munda et immaculáta apud Deum et Patrem hæc est: Visitáre pupíllos et viduas in tribulatióne eórum, et immaculátum se custodíre ab hoc sǽculo."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Surréxit Christus, et illúxit nobis, quos rédemit sánguine suo. Allelúja.","mark":"V"},{"k":"ref","la":"Joannes 16:28"},{"k":"text","la":"Exívi a Patre, et veni in mundum: íterum relínquo mundum, et vado ad Patrem. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 16:23-30"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Amen, amen, dico vobis: si quid petiéritis Patrem in nómine meo, dabit vobis. Usque modo non petístis quidquam in nómine meo: Pétite, et accipiétis, ut gáudium vestrum sit plenum. Hæc in provérbiis locútus sum vobis. Venit hora, cum jam non in provérbiis loquar vobis, sed palam de Patre annuntiábo vobis. In illo die in nómine meo petétis: et non dico vobis, quia ego rogábo Patrem de vobis: ipse enim Pater amat vos, quia vos me amástis, et credidístis quia ego a Deo exívi. Exívi a Patre et veni in mundum: íterum relínquo mundum et vado ad Patrem. Dicunt ei discípuli ejus: Ecce, nunc palam loquéris et provérbium nullum dicis. Nunc scimus, quia scis ómnia et non opus est tibi, ut quis te intérroget: in hoc crédimus, quia a Deo exísti."}],"Offertorium":[{"k":"ref","la":"Ps 65:8-9; 65:20"},{"k":"text","la":"Benedícite, gentes, Dóminum, Deum nostrum, et obaudíte vocem laudis ejus: qui pósuit ánimam meam ad vitam, et non dedit commovéri pedes meos: benedíctus Dóminus, qui non amóvit deprecatiónem meam et misericórdiam suam a me, allelúja."}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, fidélium preces cum oblatiónibus hostiárum: ut, per hæc piæ devotiónis offícia, ad cœléstem glóriam transeámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 95:2"},{"k":"text","la":"Cantáte Dómino, allelúja: cantáte Dómino et benedícite nomen ejus: bene nuntiáte de die in diem salutáre ejus, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Tríbue nobis, Dómine, cæléstis mensæ virtúte satiátis: et desideráre, quæ recta sunt, et desideráta percípere."},{"k":"macro","name":"Per Dominum"}]},"hr":{"220adaabf86db148":{"t":"Iz 48, 20, Ps 65, 1-2\n(Iz 48, 20) Navijestite radosnu riječ da se čuje, <i>aleluja</i>.\nNavijestite do kraja zemlje: Oslobodio je Bog svoj narod, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 65, 1-2) Kličite Bogu, sve zemlje, pjevajte pjesmu imenu njegovu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 48, 20) Navijestite radosnu riječ da se čuje, <i>aleluja</i>.\nNavijestite do kraja zemlje: Oslobodio je Bog svoj narod, <i>aleluja</i>, <i>aleluja</i>."},"a2273fd2a27e344c":{"t":"<i>Pomolimo se</i>.\nBože, od koga proizlaze sva dobra, podaj nama koji ti se molimo da po tvojem nadahnuću mislimo što je pravo i pod tvojim vodstvom da to činimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"3db4c0fa95bb077d":{"t":"Jak 1, 22-27\nČitanje Poslanice bl. Jakova apostola. Predragi: budite izvršioci riječi a ne samo slušaoci koji varaju sami sebe. Jer ako tko sluša riječ, a ne živi po njoj, sličan je čovjeku koji sebe promatra u ogledalu: kad se pogledao, otiđe i odmah zaboravi kakav je. – Tko temeljito promatra savršeni zakon slobode i ustraje u njemu te ne bude zaboravljiv slušalac nego izvršitelj djela, taj će biti blažen u svojem djelu. – Ako tko misli da je pobožan, a ne obuzdava svojega jezika, nego zavarava sebe, njegova je pobožnost isprazna. Ovo je čista i neokaljana pobožnost pred Bogom i Ocem: brinuti se za sirote i udovice u njihovoj nevolji i čuvati se neokaljanim od ovoga svijeta."},"e28abe3e36b0e886":{"t":"Iv 16, 28\n<i>Aleluja</i>, <i>aleluja</i>.\nKrist je uskrsnuo i prosvijetlio nas koje je otkupio svojom krvlju, <i>aleluja</i>.\n(Iv 16, 28) Izišao sam od Oca i došao na svijet, sad opet ostavljam svijet i idem Ocu, <i>aleluja</i>."},"64a0154e42419dd9":{"t":"Iv 16, 23-30\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: reče Isus svojim učenicima: Zaista, zaista vam kažem: ako što zatražite od Oca u moje ime, dat će vam. Dosada ništa niste molili u moje ime. Molite i primit ćete i vaša će radost biti potpuna. Ovo sam vam govorio u slikama, ali će doći vrijeme, kada vam neću više govoriti u slikama, nego ću vam otvoreno kazati o Ocu. Onda ćete moliti u moje ime. Ne kažem vam da ću ja moliti Oca za vas, jer sam Otac vas ljubi, stoga što ste vi mene ljubili i što ste vjerovali, da sam izišao od Boga. Izišao sam od Oca i došao na svijet. Sad opet ostavljam svijet i vraćam se Ocu. Rekoše mu njegovi učenici: Eto, sad otvoreno govoriš i ne upotrebljavaš nikakve slike. Sada znamo da sve znaš i ne treba da te tko pita. Zato vjerujemo da si izišao od Boga."},"737e5c98a96e3404":{"t":"Ps 65, 8-9 i 20\nBlagoslivljajte, narodi, Gospodina našega Boga i navješćujte njegovu hvalu, jer on je dao život mojoj duši i nije dopustio, da mi se spotakne noga. Blagoslovljen Bog, koji nije odbio moje molitve, niti odvratio svoga milosrđa od mene, <i>aleluja</i>."},"0fd2e8f96ba76c4c":{"t":"Sa žrtvenim prinosima primi, Gospodine, i molitve svojih vjernika da po ovoj službi pobožne odanosti prijeđemo u nebesku slavu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"aa68f0aee886ab03":{"t":"Ps 95, 2\nPjevajte Gospodinu, aleluja, pjevajte Gospodinu i blagoslivljajte njegovo ime. Naviještajte iz dana u dan njegovo spasenje, <i>aleluja</i>, <i>aleluja</i>."},"75d9734be7b054fc":{"t":"<i>Pomolimo se</i>.\nUdijeli, Gospodine, nama koji smo nasićeni snagom s nebeskog stola da težimo za onim što je pravo i da postignemo ono za čim težimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
